INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('cc1f83a0-fb7d-45f9-9a04-366ccc54a58d', '73d587b2-66ba-44f7-b935-329aef0aadc1', '11', 'Subcontractors/Consultants', '{"version":1,"metadata":{"title":"Subcontractors/Consultants","proposal_id":"73d587b2-66ba-44f7-b935-329aef0aadc1","version_number":1,"status":"in_progress"},"canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"max_pages":10,"min_font_size":10,"font_default":{"family":"Times New Roman","size":11},"line_spacing":1,"header":null,"footer":null,"max_slides":null},"nodes":[{"id":"nxtduimqpyhp","type":"heading","content":{"level":2,"text":"Subcontractors/Consultants"},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false},{"id":"n2we9de86id3","type":"text_block","content":{"text":"A robotics consultant supports print-path generation (under 15% of effort). No other subcontractors are proposed for Phase I."},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false}]}', 10, 'approved', NULL, '{}', NULL, 2, '2026-08-10T00:08:22.354Z'::timestamptz, '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T00:13:30.796Z'::timestamptz, true, '2026-08-10T00:13:30.796Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Technical Volume', 2, NULL, '{}', '{"itemType":"text","volumeName":"Technical Volume","expertNotes":null}'::jsonb, '286e52ef-1b01-495d-a18a-2913077c6177', 11, 'human_edit') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('ec5d73bf-881d-40d1-8f05-605c005ef993', '73d587b2-66ba-44f7-b935-329aef0aadc1', '2', 'Identification and Significance of the Problem or Opportunity', '{"version":1,"metadata":{"title":"Identification and Significance of the Problem or Opportunity","proposal_id":"73d587b2-66ba-44f7-b935-329aef0aadc1","version_number":1,"status":"in_progress"},"canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"max_pages":10,"min_font_size":10,"font_default":{"family":"Times New Roman","size":11},"line_spacing":1,"header":null,"footer":null,"max_slides":null},"nodes":[{"id":"nyjbkg80e2c","type":"heading","content":{"level":2,"text":"Identification and Significance of the Problem or Opportunity"},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false},{"id":"nxuyuiau1l6f","type":"text_block","content":{"text":"Expeditionary basing requires protective and operational structures built rapidly with minimal logistics. Foundation 3DCP is commercializing a licensed external-gate concrete-extrusion system that prints structural walls directly from locally-sourced aggregate, collapsing the formwork and skilled-labor burden. This Phase I validates the approach for expeditionary construction."},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false}]}', 10, 'approved', NULL, '{}', NULL, 3, '2026-08-10T00:08:22.354Z'::timestamptz, '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T00:13:30.392Z'::timestamptz, true, '2026-08-10T00:13:30.392Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Technical Volume', 2, NULL, '{}', '{"itemType":"text","volumeName":"Technical Volume","expertNotes":null}'::jsonb, '286e52ef-1b01-495d-a18a-2913077c6177', 2, 'human_edit') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('fbeffad8-9571-4f30-99d8-d96d5ec7836d', '73d587b2-66ba-44f7-b935-329aef0aadc1', '5', 'Related Work', '{"version":1,"metadata":{"title":"Related Work","proposal_id":"73d587b2-66ba-44f7-b935-329aef0aadc1","version_number":1,"status":"in_progress"},"canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"max_pages":10,"min_font_size":10,"font_default":{"family":"Times New Roman","size":11},"line_spacing":1,"header":null,"footer":null,"max_slides":null},"nodes":[{"id":"nn60vx4pl4f8","type":"heading","content":{"level":2,"text":"Related Work"},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false},{"id":"nvn2xjtqqfxg","type":"text_block","content":{"text":"Foundation 3DCP has printed full residential foundation walls under prior R&D and a state-funded pilot. Army ERDC has demonstrated additive construction of expeditionary structures (ACES), establishing DoW interest and a transition venue."},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false}]}', 10, 'approved', NULL, '{}', NULL, 2, '2026-08-10T00:08:22.354Z'::timestamptz, '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T00:13:30.524Z'::timestamptz, true, '2026-08-10T00:13:30.524Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Technical Volume', 2, NULL, '{}', '{"itemType":"text","volumeName":"Technical Volume","expertNotes":null}'::jsonb, '286e52ef-1b01-495d-a18a-2913077c6177', 5, 'human_edit') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('13de9d89-150d-4643-819d-6fa33ed409f4', '73d587b2-66ba-44f7-b935-329aef0aadc1', '7', 'Commercialization Strategy', '{"version":1,"metadata":{"title":"Commercialization Strategy","proposal_id":"73d587b2-66ba-44f7-b935-329aef0aadc1","version_number":1,"status":"in_progress"},"canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"max_pages":10,"min_font_size":10,"font_default":{"family":"Times New Roman","size":11},"line_spacing":1,"header":null,"footer":null,"max_slides":null},"nodes":[{"id":"ng04yt7zoi1j","type":"heading","content":{"level":2,"text":"Commercialization Strategy"},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false},{"id":"n4wbc0t7ganf","type":"text_block","content":{"text":"Dual-use: DoW expeditionary basing plus the civil residential-foundation market that is Foundation 3DCP''s commercial beachhead. The external-gate IP is available to be licensed, de-risking transition for a defense prime."},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false}]}', 10, 'approved', NULL, '{}', NULL, 2, '2026-08-10T00:08:22.354Z'::timestamptz, '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T00:13:30.620Z'::timestamptz, true, '2026-08-10T00:13:30.620Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Technical Volume', 2, NULL, '{}', '{"itemType":"text","volumeName":"Technical Volume","expertNotes":null}'::jsonb, '286e52ef-1b01-495d-a18a-2913077c6177', 7, 'human_edit') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('32708010-225f-465d-94cb-e328ac0e054a', '73d587b2-66ba-44f7-b935-329aef0aadc1', '9', 'Foreign Citizens', '{"version":1,"metadata":{"title":"Foreign Citizens","proposal_id":"73d587b2-66ba-44f7-b935-329aef0aadc1","version_number":1,"status":"in_progress"},"canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"max_pages":10,"min_font_size":10,"font_default":{"family":"Times New Roman","size":11},"line_spacing":1,"header":null,"footer":null,"max_slides":null},"nodes":[{"id":"nk831gvwag3","type":"heading","content":{"level":2,"text":"Foreign Citizens"},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false},{"id":"n1jd0005xvld","type":"text_block","content":{"text":"No foreign nationals are proposed for work on this effort. Any change will be disclosed to the contracting officer with country of citizenship prior to participation, per DSIP requirements."},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false}]}', 10, 'approved', NULL, '{}', NULL, 2, '2026-08-10T00:08:22.354Z'::timestamptz, '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T00:13:30.710Z'::timestamptz, true, '2026-08-10T00:13:30.710Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Technical Volume', 2, NULL, '{}', '{"itemType":"text","volumeName":"Technical Volume","expertNotes":null}'::jsonb, '286e52ef-1b01-495d-a18a-2913077c6177', 9, 'human_edit') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('5a6cb456-e9d6-4d71-a846-2b437c60206c', '73d587b2-66ba-44f7-b935-329aef0aadc1', '8', 'Key Personnel', '{"version":1,"metadata":{"title":"Key Personnel","proposal_id":"73d587b2-66ba-44f7-b935-329aef0aadc1","version_number":1,"status":"in_progress"},"canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"max_pages":10,"min_font_size":10,"font_default":{"family":"Times New Roman","size":11},"line_spacing":1,"header":null,"footer":null,"max_slides":null},"nodes":[{"id":"ndp2iz2hayyp","type":"heading","content":{"level":2,"text":"Key Personnel"},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false},{"id":"nwm28addycff","type":"text_block","content":{"text":"The Principal Investigator leads extrusion-system development and holds the external-gate license; the co-PI leads print-path and load characterization. Both are U.S. citizens committing majority effort."},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false}]}', 10, 'approved', NULL, '{}', NULL, 2, '2026-08-10T00:08:22.354Z'::timestamptz, '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T00:13:30.669Z'::timestamptz, true, '2026-08-10T00:13:30.669Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Technical Volume', 2, 'team', '{}', '{"itemType":"text","volumeName":"Technical Volume","expertNotes":null}'::jsonb, '286e52ef-1b01-495d-a18a-2913077c6177', 8, 'human_edit') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('dd6aad6b-a1f8-4c2c-90ef-7965e56e3aa6', '73d587b2-66ba-44f7-b935-329aef0aadc1', '3', 'Phase I Technical Objectives', '{"version":1,"metadata":{"title":"Phase I Technical Objectives","proposal_id":"73d587b2-66ba-44f7-b935-329aef0aadc1","version_number":1,"status":"in_progress"},"canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"max_pages":10,"min_font_size":10,"font_default":{"family":"Times New Roman","size":11},"line_spacing":1,"header":null,"footer":null,"max_slides":null},"nodes":[{"id":"n6apmmgcboq9","type":"heading","content":{"level":2,"text":"Phase I Technical Objectives"},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false},{"id":"nn50c4ldl4vl","type":"text_block","content":{"text":"Objective 1: validate print fidelity of the external-gate head with field-representative aggregate. Objective 2: characterize green-strength and cure profiles across field conditions. Objective 3: demonstrate a print-path for a representative 12x12 ft protective structure. Objective 4: define the ruggedized print-head and logistics envelope for Phase II."},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false}]}', 10, 'approved', NULL, '{}', NULL, 3, '2026-08-10T00:08:22.354Z'::timestamptz, '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T00:13:30.437Z'::timestamptz, true, '2026-08-10T00:13:30.437Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Technical Volume', 2, 'technical.objectives', '{}', '{"itemType":"text","volumeName":"Technical Volume","expertNotes":null}'::jsonb, '286e52ef-1b01-495d-a18a-2913077c6177', 3, 'human_edit') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('f047a674-8ae7-4def-baef-3cdcc92f1d3e', '73d587b2-66ba-44f7-b935-329aef0aadc1', '4', 'Phase I Statement of Work', '{"version":1,"metadata":{"title":"Phase I Statement of Work","proposal_id":"73d587b2-66ba-44f7-b935-329aef0aadc1","version_number":1,"status":"in_progress"},"canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"max_pages":10,"min_font_size":10,"font_default":{"family":"Times New Roman","size":11},"line_spacing":1,"header":null,"footer":null,"max_slides":null},"nodes":[{"id":"nhzi8o7ey2ha","type":"heading","content":{"level":2,"text":"Phase I Statement of Work"},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false},{"id":"nuhcqu40q2zq","type":"text_block","content":{"text":"Task 1: adapt the external-gate head to field aggregate. Task 2: green-strength and cure characterization. Task 3: bench-scale 12x12 structure print. Task 4: ruggedization requirements and the Phase II demonstration plan. Monthly reports and a Phase I final report are delivered."},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false}]}', 10, 'approved', NULL, '{}', NULL, 3, '2026-08-10T00:08:22.354Z'::timestamptz, '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T00:13:30.478Z'::timestamptz, true, '2026-08-10T00:13:30.478Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Technical Volume', 2, NULL, '{}', '{"itemType":"text","volumeName":"Technical Volume","expertNotes":null}'::jsonb, '286e52ef-1b01-495d-a18a-2913077c6177', 4, 'human_edit') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('331394f6-10fd-4013-860f-3340e16b236e', '73d587b2-66ba-44f7-b935-329aef0aadc1', '10', 'Facilities/Equipment', '{"version":1,"metadata":{"title":"Facilities/Equipment","proposal_id":"73d587b2-66ba-44f7-b935-329aef0aadc1","version_number":1,"status":"in_progress"},"canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"max_pages":10,"min_font_size":10,"font_default":{"family":"Times New Roman","size":11},"line_spacing":1,"header":null,"footer":null,"max_slides":null},"nodes":[{"id":"nvrwh5i8eze","type":"heading","content":{"level":2,"text":"Facilities/Equipment"},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false},{"id":"n81ii5kxod8a","type":"text_block","content":{"text":"Foundation 3DCP operates a printing bay with the licensed external-gate system, a materials-characterization bench, and load-test fixtures sufficient for all Phase I tasks. No government-furnished equipment is required."},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false}]}', 10, 'approved', NULL, '{}', NULL, 2, '2026-08-10T00:08:22.354Z'::timestamptz, '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T00:13:30.756Z'::timestamptz, true, '2026-08-10T00:13:30.756Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Technical Volume', 2, 'facilities', '{}', '{"itemType":"text","volumeName":"Technical Volume","expertNotes":null}'::j