INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('b88eb9bd-ec06-41d6-95b4-fbdc47e2de18', '73d587b2-66ba-44f7-b935-329aef0aadc1', '6', 'Relationship with Future Research or Research and Development', '{"version":1,"metadata":{"title":"Relationship with Future Research or Research and Development","proposal_id":"73d587b2-66ba-44f7-b935-329aef0aadc1","version_number":1,"status":"in_progress"},"canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"max_pages":10,"min_font_size":10,"font_default":{"family":"Times New Roman","size":11},"line_spacing":1,"header":null,"footer":null,"max_slides":null},"nodes":[{"id":"n3sfpb20p6wl","type":"heading","content":{"level":2,"text":"Relationship with Future Research or Research and Development"},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false},{"id":"n6jh4yvjpcrh","type":"text_block","content":{"text":"Phase I de-risks field-aggregate and ruggedization. Phase II builds and demonstrates a transportable print cell at a test range. Phase III transitions to dual-use deployment for expeditionary basing and printed residential foundations."},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false}]}', 10, 'approved', NULL, '{}', NULL, 2, '2026-08-10T00:08:22.354Z'::timestamptz, '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T00:13:30.572Z'::timestamptz, true, '2026-08-10T00:13:30.572Z'::timestamptz, 'bd101904-582d-44db