INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('65201c40-0d77-4fd1-adbe-17210b128cd3', '73d587b2-66ba-44f7-b935-329aef0aadc1', '12', 'Prior, Current, or Pending Support of Similar Proposals or Awards', '{"version":1,"metadata":{"title":"Prior, Current, or Pending Support of Similar Proposals or Awards","proposal_id":"73d587b2-66ba-44f7-b935-329aef0aadc1","version_number":1,"status":"in_progress"},"canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"max_pages":10,"min_font_size":10,"font_default":{"family":"Times New Roman","size":11},"line_spacing":1,"header":null,"footer":null,"max_slides":null},"nodes":[{"id":"n2pp376zywo","type":"heading","content":{"level":2,"text":"Prior, Current, or Pending Support of Similar Proposals or Awards"},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false},{"id":"nivgn39mnbog","type":"text_block","content":{"text":"The external-gate development received prior non-federal support (Ohio TVSF pilot). No current or pending federal proposals overlap this Phase I scope. Foundation 3DCP certifies no duplication of funded effort."},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false}]}', 10, 'approved', NULL, '{}', NULL, 2, '2026-08-10T00:08:22.354Z'::timestamptz, '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T00:13:30.834Z'::timestamptz, true, '2026-08-10T00:13:30.834Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Technical Volume', 2, NULL, '{}', '{"itemType":"text","volumeName":"Technical Volume","expertNotes":null}'::jsonb, '286e52ef-1b01-495d-a18a-2913077c6177', 12, 'human_edit') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('c2158a96-f22f-4e0d-8a3b-c41964d25029', '73d587b2-66ba-44f7-b935-329aef0aadc1', '13', 'Identification and Assertion of Restrictions on the Government''s Use, Release, or Disclosure of Technical Data or Computer Software', '{"version":1,"metadata":{"title":"Identification and Assertion of Restrictions on the Government''s Use, Release, or Disclosure of Technical Data or Computer Software","proposal_id":"73d587b2-66ba-44f7-b935-329aef0aadc1","version_number":1,"status":"in_progress"},"canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"max_pages":10,"min_font_size":10,"font_default":{"family":"Times New Roman","size":11},"line_spacing":1,"header":null,"footer":null,"max_slides":null},"nodes":[{"id":"ngl1qwc4qzer","type":"heading","content":{"level":2,"text":"Identification and Assertion of Restrictions on the Government''s Use, Release, or Disclosure of Technical Data or Computer Software"},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false},{"id":"ndfewye31f94","type":"text_block","content":{"text":"Foundation 3DCP asserts SBIR data rights in the external-gate print-control methods and mix parameters developed at private expense. A full list of asserted restrictions is provided per the DFARS SBIR data-rights clause."},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false}]}', 10, 'approved', NULL, '{}', NULL, 2, '2026-08-10T00:08:22.354Z'::timestamptz, '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-10T00:13:31.143Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T00:13:30.871Z'::timestamptz, true, '2026-08-10T00:13:30.871Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Technical Volume', 2, NULL, '{}', '{"itemType":"text","volumeName":"Technical Volume","expertNotes":null}'::jsonb, '286e52ef-1b01-495d-a18a-2913077c6177', 13, 'human_edit') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('18e9a018-885c-4456-8e1f-08531e3a8044', 'fa1461c9-806c-4541-b914-15d4bd39749a', '2', 'Phase I Proof of Feasibility — Identification and Significance of the Problem/Opportunity', '{"version":1,"metadata":{"title":"Phase I Proof of Feasibility — Identification and Significance of the Problem/Opportunity","proposal_id":"fa1461c9-806c-4541-b914-15d4bd39749a","version_number":1,"status":"in_progress"},"canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"max_pages":30,"min_font_size":10,"font_default":{"family":"Times New Roman","size":11},"line_spacing":1,"header":null,"footer":null,"max_slides":null},"nodes":[{"id":"n56l9tjxmpu9","type":"heading","content":{"level":2,"text":"Phase I Proof of Feasibility — Identification and Significance of the Problem/Opportunity"},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false},{"id":"nb7kd9x1noq","type":"text_block","content":{"text":"Large-scale concrete additive manufacturing is limited by manual print-path control and mix inconsistency in the field. Foundation 3DCP, with a university materials-science partner, proposes an autonomous large-scale concrete additive-manufacturing cell. Direct-to-Phase-II is justified by Phase I-equivalent feasibility already demonstrated."},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false}]}', 30, 'approved', NULL, '{}', NULL, 3, '2026-08-10T00:08:26.589Z'::timestamptz, '2026-08-10T00:13:33.139Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-10T00:13:33.139Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T00:13:32.599Z'::timestamptz, true, '2026-08-10T00:13:32.599Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Technical Volume', 2, NULL, '{}', '{"itemType":"text","volumeName":"Technical Volume","expertNotes":null}'::jsonb, '997d6af2-8fec-45a0-9be9-07c016ac1cae', 2, 'human_edit') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('c971af65-96db-49be-b8a5-791d13f87fe8', 'fa1461c9-806c-4541-b914-15d4bd39749a', '3', 'Phase I Proof of Feasibility — Results Demonstrating Technical Merit and Feasibility', '{"version":1,"metadata":{"title":"Phase I Proof of Feasibility — Results Demonstrating Technical Merit and Feasibility","proposal_id":"fa1461c9-806c-4541-b914-15d4bd39749a","version_number":1,"status":"in_progress"},"canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"max_pages":30,"min_font_size":10,"font_default":{"family":"Times New Roman","size":11},"line_spacing":1,"header":null,"footer":null,"max_slides":null},"nodes":[{"id":"nrmr877napkj","type":"heading","content":{"level":2,"text":"Phase I Proof of Feasibility — Results Demonstrating Technical Merit and Feasibility"},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false},{"id":"nnm0sjag0l3","type":"text_block","content":{"text":"Under prior R&D and a state-funded pilot, Foundation 3DCP printed a full residential foundation wall using the licensed external-gate system, cutting foundation labor ~336->25 hours and formwork/material cost 47-65%. These results demonstrate structural-scale printing with common local concrete, satisfying the D2P2 feasibility bar."},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false}]}', 30, 'approved', NULL, '{}', NULL, 3, '2026-08-10T00:08:26.589Z'::timestamptz, '2026-08-10T00:13:33.139Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-10T00:13:33.139Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T00:13:32.648Z'::timestamptz, true, '2026-08-10T00:13:32.648Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Technical Volume', 2, NULL, '{}', '{"itemType":"text","volumeName":"Technical Volume","expertNotes":null}'::jsonb, '997d6af2-8fec-45a0-9be9-07c016ac1cae', 3, 'human_edit') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('b06635bd-d013-4d54-96e9-59d2b95a0df8', 'fa1461c9-806c-4541-b914-15d4bd39749a', '6', 'Snapshot of Proposed Phase II Effort — Statement of Work', '{"version":1,"metadata":{"title":"Snapshot of Proposed Phase II Effort — Statement of Work","proposal_id":"fa1461c9-806c-4541-b914-15d4bd39749a","version_number":1,"status":"in_progress"},"canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"max_pages":30,"min_font_size":10,"font_default":{"family":"Times New Roman","size":11},"line_spacing":1,"header":null,"footer":null,"max_slides":null},"nodes":[{"id":"nsld3vmquuk","type":"heading","content":{"level":2,"text":"Snapshot of Proposed Phase II Effort — Statement of Work"},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false},{"id":"ndmfbs7f3fi8","type":"text_block","content":{"text":"Phase II tasks integrate autonomous navigation, closed-loop rheology sensing with the research institution, full-scale continuous-print demonstrations, and a ruggedized transition package over 24 months."},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false}]}', 30, 'approved', NULL, '{}', NULL, 2, '2026-08-10T00:08:26.589Z'::timestamptz, '2026-08-10T00:13:33.139Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-10T00:13:33.139Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T00:13:32.742Z'::timestamptz, true, '2026-08-10T00:13:32.742Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Technical Volume', 2, NULL, '{}', '{"itemType":"text","volumeName":"Technical Volume","expertNotes":null}'::jsonb, '997d6af2-8fec-45a0-9be9-07c016ac1cae', 6, 'human_edit') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('51bffb5c-24c0-494b-8913-edf1ee77e432', 'fa1461c9-806c-4541-b914-15d4bd39749a', '7', 'STTR Cooperative R&D Work-Split Plan (SB >= 40% / RI >= 30%)', '{"version":1,"metadata":{"title":"STTR Cooperative R&D Work-Split Plan (SB >= 40% / RI >= 30%)","proposal_id":"fa1461c9-806c-4541-b914-15d4bd39749a","version_number":1,"status":"in_progress"},"canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"max_pages":30,"min_font_size":10,"font_default":{"family":"Times New Roman","size":11},"line_spacing":1,"header":null,"footer":null,"max_slides":null},"nodes":[{"id":"nwe1a366r8v","type":"heading","content":{"level":2,"text":"STTR Cooperative R&D Work-Split Plan (SB >= 40% / RI >= 30%)"},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false},{"id":"n0ioltbbm6jsv","type":"text_block","content":{"text":"Foundation 3DCP (small business concern) leads system integration, print-head hardening, and field demonstration at 55% of budget, satisfying the STTR small-business minimum of 40%. The university Materials Science group (research institution) leads autonomous mix-design and rheology control at 35%, satisfying the research-institution minimum of 30%. A robotics subcontractor supports navigation at 10%. Percentages are measured by direct and indirect costs. Allocation of rights is documented in Volume 5."},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false}]}', 30, 'approved', NULL, '{}', NULL, 2, '2026-08-10T00:08:26.589Z'::timestamptz, '2026-08-10T00:13:33.139Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-10T00:13:33.139Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T00:13:32.776Z'::timestamptz, true, '2026-08-10T00:13:32.776Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Technical Volume', 2, NULL, '{}', '{"itemType":"text","volumeName":"Technical Volume","expertNotes":null}'::jsonb, '997d6af2-8fec-45a0-9be9-07c016ac1cae', 7, 'human_edit') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('8d557021-5af8-4ed0-b26b-03f866a7b436', 'fa1461c9-806c-4541-b914-15d4bd39749a', '11', 'Subcontractors/Consultants', '{"version":1,"metadata":{"title":"Subcontractors/Consultants","proposal_id":"fa1461c9-806c-4541-b914-15d4bd39749a","version_number":1,"status":"in_progress"},"canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"max_pages":30,"min_font_size":10,"font_default":{"family":"Times New Roman","size":11},"line_spacing":1,"header":null,"footer":null,"max_slides":null},"nodes":[{"id":"n5dlt3p8h1eo","type":"heading","content":{"level":2,"text":"Subcontractors/Consultants"},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false},{"id":"nhs1scs32yae","type":"text_block","content":{"text":"A robotics subcontractor supports autonomous print-path navigation (10% of effort). The research institution is engaged under the STTR cooperative arrangement, not as a subcontractor."},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false}]}', 30, 'approved', NULL, '{}', NULL, 2, '2026-08-10T00:08:26.589Z'::timestamptz, '2026-08-10T00:13:33.139Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-10T00:13:33.139Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T00:13:32.896Z'::timestamptz, true, '2026-08-10T00:13:32.896Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Technical Volume', 2, NULL, '{}', '{"itemType":"text","volumeName":"Technical Volume","expertNotes":null}'::jsonb, '997d6af2-8fec-45a0-9be9-07c016ac1cae', 11, 'human_edit') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('faa7bbc8-f84f-4308-a491-429baa8fa83e', 'fa1461c9-806c-4541-b914-15d4bd39749a', '10', 'Facilities/Equipment (Small Business Concern + Research Institution)', '{"version":1,"metadata":{"title":"Facilities/Equipment (Small Business Concern + Research Institution)","proposal_id":"fa1461c9-806c-4541-b914-15d4bd39749a","version_number":1,"status":"in_progress"},"canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"max_pages":30,"min_font_size":10,"font_default":{"family":"Times New Roman","size":11},"line_spacing":1,"header":null,"footer":null,"max_slides":null},"nodes":[{"id":"n3to5l96dj8j","type":"heading","content":{"level":2,"text":"Facilities/Equipment (Small Business Concern + Research Institution)"},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false},{"id":"nq4kuqshzyy","type":"text_block","content":{"text":"Foundation 3DCP provides the licensed external-gate printing bay and load-test fixtures; the research institution provides materials-characterization and rheology instrumentation. No government-furnished equipment is required."},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false}]}', 30, 'approved', NULL, '{}', NULL, 2, '2026-08-10T00:08:26.589Z'::timestamptz, '2026-08-10T00:13:33.139Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-10T00:13:33.139Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T00:13:32.869Z'::timestamptz, true, '2026-08-10T00:13:32.869Z'::timestamptz, 'bd1019