INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('85a5295a-ddde-4ea8-b321-d23b2271c460', 'fa1461c9-806c-4541-b914-15d4bd39749a', '4', 'Phase I Proof of Feasibility — Related Work and Prior Results', '{"version":1,"metadata":{"title":"Phase I Proof of Feasibility — Related Work and Prior Results","proposal_id":"fa1461c9-806c-4541-b914-15d4bd39749a","version_number":1,"status":"in_progress"},"canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"max_pages":30,"min_font_size":10,"font_default":{"family":"Times New Roman","size":11},"line_spacing":1,"header":null,"footer":null,"max_slides":null},"nodes":[{"id":"n9yimvuecwwe","type":"heading","content":{"level":2,"text":"Phase I Proof of Feasibility — Related Work and Prior Results"},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false},{"id":"njew0vc5nrqa","type":"text_block","content":{"text":"Prior results include instrumented print runs, cure characterization, and a printed foundation demonstration. The university partner contributes closed-loop rheology and autonomous mix-design research relevant to Phase II scale-up."},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false}]}', 30, 'approved', NULL, '{}', NULL, 3, '2026-08-10T00:08:26.589Z'::timestamptz, '2026-08-10T00:13:33.139Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-10T00:13:33.139Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T00:13:32.683Z'::timestamptz, true, '2026-08-10T00:13:32.683Z'::timestamptz, 'bd101904-582d-44db-ac2