INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('a1d48a72-5736-4b2a-a369-ae57d2cd01d0', 'fa1461c9-806c-4541-b914-15d4bd39749a', '5', 'Snapshot of Proposed Phase II Effort — Technical Objectives', '{"version":1,"metadata":{"title":"Snapshot of Proposed Phase II Effort — Technical Objectives","proposal_id":"fa1461c9-806c-4541-b914-15d4bd39749a","version_number":1,"status":"in_progress"},"canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"max_pages":30,"min_font_size":10,"font_default":{"family":"Times New Roman","size":11},"line_spacing":1,"header":null,"footer":null,"max_slides":null},"nodes":[{"id":"ntfu50maigfc","type":"heading","content":{"level":2,"text":"Snapshot of Proposed Phase II Effort — Technical Objectives"},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false},{"id":"n84206ln277","type":"text_block","content":{"text":"Objective 1: autonomous, GPS-denied print-path navigation. Objective 2: closed-loop rheology feedback. Objective 3: multi-day continuous structural prints with documented load performance. Objective 4: a transition-ready autonomous large-scale concrete additive-manufacturing cell."},"style":{},"provenance":{"source":"manual"},"history":[],"library_eligible":false}]}', 30, 'approved', NULL, '{}', NULL, 2, '2026-08-10T00:08:26.589Z'::timestamptz, '2026-08-10T00:13:33.139Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'draft', '2026-08-10T00:13:33.139Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T00:13:32.711Z'::timestamptz, true, '2026-08-10T00:13:32.